            for cb in range(c0,c1+1):
                a,b=rseg[rb]; e,f=cseg[cb]
                for i in range(a,b+1):
                    for j in range(e,f+1):
                        cells.add((i,j))
        fills[v]=cells
    allc=set().union(*fills.values())
    for i,j in allc:
        vs=[v for v in fills if (i,j) in fills[v]]
        out[i][j]= 6 if len(vs)>1 else vs[0]
    return out

