def transform(grid):
    n=len(grid)
    rs=[i for i in range(n) if all(grid[i][j]==8 for j in range(n))]
    cs=[j for j in range(n) if all(grid[i][j]==8 for i in range(n))]
    def segments(seps):
        segs=[]; s=0
        for x in seps+[n]: segs.append((s,x-1)); s=x+1
        return segs
    rseg=segments(rs); cseg=segments(cs)
    def blk(segs,i):
        for k,(a,b) in enumerate(segs):
            if a<=i<=b: return k
    marks={}
    for i in range(n):
        for j in range(n):
            v=grid[i][j]
            if v not in (0,8): marks.setdefault(v,[]).append((blk(rseg,i),blk(cseg,j)))
    out=[row[:] for row in grid]
    fills={}
    for v,pts in marks.items():
        cells=set()
        from collections import defaultdict
        rows=defaultdict(list); cols=defaultdict(list)
        for rb,cb in pts: rows[rb].append(cb); cols[cb].append(rb)
        for rb,cbs in rows.items():
            if len(cbs)>=2:
                a,b=rseg[rb]
                for cb in range(min(cbs),max(cbs)+1):
                    e,f=cseg[cb]
                    for i in range(a,b+1):
                        for j in range(e,f+1): cells.add((i,j))
        for cb,rbs in cols.items():
            if len(rbs)>=2:
                e,f=cseg[cb]
                for rb in range(min(rbs),max(rbs)+1):
                    a,b=rseg[rb]
                    for i in range(a,b+1):
                        for j in range(e,f+1): cells.add((i,j))
        fills[v]=cells
    allc=set().union(*fills.values()) if fills else set()
    for i,j in allc:
        vs=[v for v in fills if (i,j) in fills[v]]
        out[i][j]=6 if len(vs)>1 else vs[0]
    return out

